"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   courses: () => (/* binding */ courses)\n/* harmony export */ });\nconst courses = [\n    {\n        \"programName\": \"Risk Management\",\n        \"slug\": \"risk-management\",\n        \"shortDescription\": \"Earn your Canadian Risk Management (CRM) designation in three courses!\",\n        \"programDescription\": \"<p>The Canadian Risk Management (CRM) designation is a widely recognized qualification that provides risk managers a foundation of knowledge and skills needed to identify, assess, monitor and limit risks. Attaining the CRM designation demonstrates a level of professional commitment, knowledge and skills that employers in both public and private sectors recognize.</p><p>This three (3) course certificate of achievement allows you to complete the educational requirements and challenge the national exams to obtain your CRM designation recognized by the Risk and Insurance Management Society (RIMS) and awarded by the Global Risk Management Institute (GRMI).</p><p>‍</p><h4>Why earn the CRM Designation?</h4><p><strong>Competitiveness</strong>:<strong> </strong>Formal training gives CRM holders a competitive advantage that employers seek.</p><p><strong>Credentials</strong>: Demonstrates that CRM holders have achieved the knowledge and skills necessary to identify, assess, monitor and limit risks.</p><p><strong>Recognition</strong>: CRM holders stand out among others in a competitive marketplace.</p><p><strong>Advancement</strong>: Improves the ability of CRM holders to achieve their organization's risk management objectives and their career goals.</p><p>‍</p>\",\n        \"programType\": \"certificate-of-achievement\",\n        \"duration\": \"2-terms\",\n        \"availabeIntakes\": \"risk-management--winter-2025\",\n        \"school\": \"chiu-school-of-business\",\n        \"programArea\": \"business\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Health and Human Services Management\",\n        \"slug\": \"health-and-human-services-management\",\n        \"shortDescription\": \"Become a leader in health and human services. Develop skills and knowledge in management by building on your health or human services diploma or degree.\",\n        \"programDescription\": \"<p>Get ready to lead. Build upon your expertise from your health or human services diploma or degree. This post-diploma certificate combines business courses with specialized health and human services leadership electives. An integrated approach to prepare you to advance your career to new levels.</p>\",\n        \"programType\": \"post-diploma-certificate\",\n        \"duration\": \"2-terms\",\n        \"availabeIntakes\": \"health-and-human-services-management-winter-2025\",\n        \"school\": \"school-of-community-studies\",\n        \"programArea\": \"community-studies\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Foundation in Entertainment Arts\",\n        \"slug\": \"foundation-in-entertainment-arts\",\n        \"shortDescription\": \"This Centre for Entertainment Arts (CEA) certificate program prepares you for advanced studies in animation, modelling, visual effects, or game development.\",\n        \"programDescription\": \"<p>The Foundation in Entertainment Arts certificate program is a full-time, one-year Centre for Entertainment Arts (CEA) program to prepare you for advanced studies in animation, modelling, visual effects, or game development. Students who are interested in a career in entertainment arts will be taught how to observe, represent, and ultimately development fundamental visual decision making skills in a variety of formats.</p><p> &nbsp;</p><p>With classes such as figure drawing, colour and design, sculpting, and more, the students will be able to create increasingly expressive, dynamic, and consistent artistic works, while establishing a well-rounded technical base. Graduates of this program will be well-positioned to pursue intermediate or advanced programs of study in line with their specific professional goals in the industry. This program welcomes students in September and January.</p><p> &nbsp;</p><p>You will receive foundational, hands-on training in the industry software and workflows. Students will also work to develop a strong personal portfolio which will help graduates gain entry into the advanced diploma programs at Centre for Entertainment Arts.<br></p><p>Software and hardware taught in this program:</p><ul><li>Adobe Creative Cloud</li><li>Adobe Photoshop</li><li>Confluence</li><li>Nuke</li><li>Maya</li><li>Blender</li><li>Microsoft Office</li><li>Substance Painter</li><li>Unreal</li><li>zBrushCore</li></ul><p>‍</p>\",\n        \"programType\": \"certificate\",\n        \"duration\": \"3-terms\",\n        \"availabeIntakes\": \"foundation-in-entertainment-arts-winter-2025\",\n        \"school\": \"centre-for-entertainment-arts\",\n        \"programArea\": \"centre-for-entertainment-arts\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Software Development - Apprenticeship Style\",\n        \"slug\": \"software-development-apprenticeship-style\",\n        \"shortDescription\": \"Gain real-world knowledge and practical experience in today’s software industry. Learn full-stack web development, mobile application development, and cloud and enterprise computing while working in your dream job.\",\n        \"programDescription\": \"<p>The Software Development - Apprenticeship Style program prepares learners for related employment in the technology industry. Learners in the program will gain practical experience in the software development industry by working-part time in a company on real-industry projects while completing an accredited college diploma. Learners gain exposure to industry standards in planning, developing, and quality assurance testing. A structured approach to problem solving, effective communications, and attention to development standards and documentation will be stressed throughout the program. Graduates will be ready for careers in full-stack web development, application development, mobile application development, database administration, and agile project management.</p>\",\n        \"programType\": \"diploma\",\n        \"duration\": \"4-terms\",\n        \"availabeIntakes\": \"software-development-apprenticeship-style-winter-2025\",\n        \"school\": \"school-of-technology\",\n        \"programArea\": \"technology\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Advanced Film Production\",\n        \"slug\": \"advanced-film-production\",\n        \"shortDescription\": \"Advanced Film Production is a full time, two-year program comprising the five principle domains of live action film development.\",\n        \"programDescription\": \"<p>Advanced Film Production is a full time, two-year program comprising the five principle domains of live action film development: Directing, Producing, Production Design, Cinematography and Postproduction. Students of the Advanced Film Production program will build in-depth knowledge around these core principle areas of filmmaking and learn the rich history of each area as well as emergent technology driving these fundamentals in filmmaking today.</p>\",\n        \"programType\": \"diploma\",\n        \"duration\": \"6-terms\",\n        \"availabeIntakes\": \"advanced-film-production-winter-2025\",\n        \"school\": \"centre-for-entertainment-arts\",\n        \"programArea\": \"centre-for-entertainment-arts\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Business Administration Diploma - Financial Services Major\",\n        \"slug\": \"business-administration-diploma-financial-services-major\",\n        \"shortDescription\": \"This sought-after career destination is for the quick thinking, ambitious professional. The financial services sector is fast paced, customer focused, and constantly innovating. Good news for those wanting a dynamic and diverse career.\",\n        \"programDescription\": '<p>As a financial professional, this program prepares you in the areas of financial planning, principles and industry standards, financial products and services, tax and legal implications, managing risks, and building customer service expertise. Graduates typically find employment in financial institutions, entering positions such as customer service representative; banking, credit or other investment management positions; finance and insurance clerks; insurance and real estate clerks; supervisors in sales and services; or investment professionals.</p><p>To learn about working financial services, <a href=\"https://bowvalleycollege.ca/-/media/bvc/school-chiu-school-of-business/images/declaration-videos-2021/revised-declaration-videos-2021/version-2-videos/financial-services-major_vo_v2.ashx?la=en&hash=17CB0206E7D0BF40561343CAFE1FA90386F56551\" target=\"_blank\"><strong>Watch Video Here</strong></a></p><p>‍</p>',\n        \"programType\": \"diploma\",\n        \"duration\": \"4-terms\",\n        \"availabeIntakes\": \"business-administration-diploma-insurance-and-risk-management-major-fall-2024; business-administration-diploma-insurance-and-risk-management-major-winter-2025\",\n        \"school\": \"chiu-school-of-business\",\n        \"programArea\": \"business\",\n        \"courseDelivery\": \"\"\n    },\n    {\n        \"programName\": \"Business Administration Diploma - Insurance and Risk Management Major\",\n        \"slug\": \"business-administration-diploma-insurance-and-risk-management-major\",\n        \"shortDescription\": \"Be a part of a dynamic industry. A career in insurance and risk management offers flexibility with client interaction, teamwork, networking, and professional growth.\",\n        \"programDescription\": \"<p>The Insurance and Risk Management major focuses on a structured approach to managing uncertainty due to threats that may emerge from the environment, technology, humans, organizations, or politics. Graduates gain the knowledge and skills to reduce these defined risks and to manage the uncertainty to an acceptable level.</p><p>To learn more about working in insurance and risk, Watch Video Here</p><p>‍</p>\",\n        \"programType\": \"diploma\",\n        \"duration\": \"4-terms\",\n        \"availabeIntakes\": \"business-administration-diploma-insurance-and-risk-management-major-fall-2024\",\n        \"school\": \"chiu-school-of-business\",\n        \"programArea\": \"business\",\n        \"courseDelivery\": \"\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/lib/courses/coursesData.tsx\n");

